# (чтение) Geze Tianjin: движения 1710/3310 по документам, KZT и валюта
b = {'1710': 0, '3310': 0}; bv = {'1710': 0, '3310': 0}
for r in q('ВЫБРАТЬ Х.Регистратор КАК Р, Х.Период КАК П, Х.СчетДт.Код КАК Дт, Х.СчетКт.Код КАК Кт, Х.Сумма КАК С, Х.ВалютнаяСуммаДт КАК ВД, Х.ВалютнаяСуммаКт КАК ВК, Х.СубконтоДт1 КАК СД, Х.СубконтоКт1 КАК СК ИЗ РегистрБухгалтерии.{REG}.ДвиженияССубконто(, , Организация.Наименование ПОДОБНО "%ANESCOM%" И (СчетДт.Код В ("1710","3310") ИЛИ СчетКт.Код В ("1710","3310")), , ) КАК Х УПОРЯДОЧИТЬ ПО Х.Период'):
    out = []
    for side, acc, k, v, sg in (('Д', r['Дт'], r['СД'], r['ВД'], 1), ('К', r['Кт'], r['СК'], r['ВК'], -1)):
        if acc in b and 'Tianjin' in s(k):
            b[acc] += sg * float(r['С']); bv[acc] += sg * float(v or 0); out.append(f'{acc}{side}')
    if out and 'курсов' not in s(r['Р']).lower() and 'Регламентная' not in s(r['Р']):
        print(' ', str(r['П'])[:10], r['Дт'], r['Кт'], f"{float(r['С']):>13,.2f}", f"1710 {b['1710']:>13,.2f}/{bv['1710']:>10,.2f} 3310 {b['3310']:>13,.2f}/{bv['3310']:>10,.2f}", s(r['Р'])[:40])
print('ИТОГ', b, bv)
